-- Exportado do Supabase para importar os dados do app no Nhost.
-- Rode no SQL Editor/conexão PostgreSQL do Nhost, com as migrations aplicadas.
-- Associa o perfil à conta Nhost pelo e-mail; preserva IDs de entidades e remapeia categorias/agendas principais existentes.
-- Este SQL importa metadados de fotos, mas não os arquivos binários do Supabase Storage.
BEGIN;
DO $$ BEGIN
  IF (SELECT count(*) FROM auth.users WHERE lower(email) = lower('bruno.ishikawa@gmail.com')) <> 1 THEN
    RAISE EXCEPTION 'Esperava encontrar exatamente uma conta Nhost para o e-mail do perfil de origem.';
  END IF;
END $$;
CREATE TEMP TABLE _nhost_user_map (source_id uuid PRIMARY KEY, target_id uuid NOT NULL);
CREATE TEMP TABLE _nhost_category_map (source_id uuid PRIMARY KEY, target_id uuid NOT NULL);
CREATE TEMP TABLE _nhost_agenda_map (source_id uuid PRIMARY KEY, target_id uuid NOT NULL);

-- Perfil: associa o ID do Supabase à conta Nhost existente.

-- Reutiliza a agenda principal criada automaticamente pelo Nhost, se ela já existir.

-- Mapeia categorias por nome/tipo para reutilizar as que já foram criadas no Nhost.

-- cartoes_credito: 3 registro(s).

-- agendas: 1 registro(s).

-- agenda_membros: 1 registro(s).

-- transacoes: 2 registro(s).

-- organizacao_itens: 7 registro(s).

-- fechamentos_mensais: 1 registro(s).

-- cartoes_controle_ma: 6 registro(s).

-- lancamentos_ma: 76 registro(s).

-- poker_sessoes_cashout: 24 registro(s).

-- poker_dias_bloqueados: 14 registro(s).

-- preferencias_acesso_modulos: 1 registro(s).

-- poker_sessoes: 10 registro(s).

-- poker_sessao_fotos: 22 registro(s).

COMMIT;

